    $$reverseString$$,
    $$function reverseString(text) {
    let out = "";
    let i = text.length - 1;
    while (i >= 0) {
        out += text[i];
    }
    return out;
}$$,
    $$function reverseString(text) {
    let out = "";
    let i = text.length - 1;
    while (i >= 0) {
        out += text[i];
        i--;
    }
    return out;
}$$,
    $$reverseString(text) should return the string backwards, so "abc" becomes "cba".$$,
    $$Calling reverseString("abc") freezes and never returns a value.$$,
    $$The index i is initialised and tested but never decremented, so the same character is appended forever and i >= 0 never becomes false. Manual index loops need three pieces — initialise, test, and step — and it's the step that's easiest to leave out when the loop body is doing something interesting.$$,
    $$[{"input":["abc"],"expected_output":"cba"},{"input":["a"],"expected_output":"a"},{"input":["debug"],"expected_output":"gubed"}]$$::jsonb,
    'published'
  )
  returning id
)
